package xyz.jovanstoiljkovic.isa.services;import org.springframework.data.repository.CrudRepository;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;import xyz.jovanstoiljkovic.isa.dtos.RegisterDTO;import xyz.jovanstoiljkovic.isa.dtos.UserDTO;import xyz.jovanstoiljkovic.isa.mappers.UserMapper;import xyz.jovanstoiljkovic.isa.models.User;import java.util.Optional;@Servicepublic class UserService extends BaseService<User>{    final private UserMapper mapper;    private BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(12);    public UserService(CrudRepository<User, Long> repo,                       UserMapper mapper) {        super(repo);        this.mapper = mapper;    }    public Optional<UserDTO> register(RegisterDTO registerDTO){        registerDTO.setPassword(encoder.encode(registerDTO.getPassword()));        User user = mapper.registerToEntity(registerDTO);        UserDTO response = mapper.entityToDTO(repo.save(user));        return Optional.of(response);    }    @Override    public Optional<User> create(User item){        item.setPassword(encoder.encode(item.getPassword()));        repo.save(item);        return Optional.of(item);    }}